package main

// LevenshteinDistance returns the minimum number of single-character edits
// required to change string a into string b.
//
// Allowed edits:
//   - insertion
//   - deletion
//   - substitution
//
// Space complexity: O(min(len(a), len(b)))
// Time complexity:  O(len(a) * len(b))
func LevenshteinDistance(a, b string) int {
	ra := []rune(a)
	rb := []rune(b)

	// Always use the shorter string for the DP row to reduce memory usage.
	if len(ra) < len(rb) {
		ra, rb = rb, ra
	}

	// rb is now the shorter string.
	prev := make([]int, len(rb)+1)
	curr := make([]int, len(rb)+1)

	// Base case: distance from empty string to prefixes of rb.
	for j := 0; j <= len(rb); j++ {
		prev[j] = j
	}

	for i := 1; i <= len(ra); i++ {
		// Distance from prefix of ra to empty string.
		curr[0] = i

		for j := 1; j <= len(rb); j++ {
			cost := 0
			if ra[i-1] != rb[j-1] {
				cost = 1
			}

			deletion := prev[j] + 1
			insertion := curr[j-1] + 1
			substitution := prev[j-1] + cost

			curr[j] = min(deletion, insertion, substitution)
		}

		// Swap rows instead of copying.
		prev, curr = curr, prev
	}

	return prev[len(rb)]
}

func min(a, b, c int) int {
	if a < b {
		if a < c {
			return a
		}
		return c
	}

	if b < c {
		return b
	}
	return c
}
